insert into public.reference_sources
  (id, branch, personnel_category, publication_number, title, chapter, career_field, proponent, official_url,
insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('da3a9d15-d095-5dcb-b2a4-1b030670e005', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-1..O-2', null, 'Lieutenant — overview', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Lieutenants must meet the requirements outlined in AR 611–110 for entry into the Aviation Branch', 'd519e411e6afdfa2ecacada7e56ab11548c61b81769415bf50e4170c4eca4171', 3, 3, null, 0, null, null, false, null),
  ('7fbd4780-6e94-5bb8-bed3-4745b8f21e6f', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'training', 'O-1..O-2', null, 'Lieutenant — Professional military education', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'All newly commissioned Aviation lieutenants attend BOLC and Initial Entry Rotary Wing training at the U.S. Army Aviation Center of Excellence (USAACE), Fort Rucker, AL. BOLC includes training on general military subjects such as leadership, weapons, combined arms operations, physical training, and warrior skills training. Initial Entry Rotary Wing or flight school, training consists of aeromedical factors, basic flight, aerodynamics, meteorology, instrument flight and combat skills training. Training is conducted from the preflight through the primary and instrument qualification phases in the LUH-72 aircraft. Basic warfighting skills, such as navigation, are trained in the LUH-72 Lakota helicopter. Students then transition into one of 4 advanced aircraft: the AH–64E Apache, UH–60A/L/M Blackhawk, C-12 Huron and CH–47F Chinook to complete day and night advance combat skills. Students must also complete survival, evasion, resistance, and escape level C training prior to being awarded the Basic Army Aviator Badge. Follow-on schooling enroute to the officer’s next assignment (for example,Airborne, Air Assault, Ranger, and Aviation Cavalry Leader’s Course) may be approved based on mission requirements.', 'eaa54518a1042d77e6e111d063a3c45ee77089f034d7e3295894f41ca31aeb9a', 3, 4, null, 1, null, null, false, null),
  ('5f287eec-3a02-5899-a5f3-edf8be659c70', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-1..O-2', null, 'Lieutenant — Key developmental assignment', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'The single most important assignment consideration for personnel managers and commanders is ensuring that the new lieutenant is assigned to a job which will allow the officer adequate opportunity to develop flight experience and troop-leading skills. Lieutenants should serve 18 to 24 months in a platoon leader position. Due to the length of flight school, this may overlap into the officer’s first year as a captain. Promotions will not automatically alter positions. Promotion from lieutenant to captain while still serving in an operational assignment such as platoon leader will not be a negative consideration when determining the officer’s potential for promotion. The overall goal is for an officer to attain pilot-in-command status and gain as much flight and leadership experience as possible prior to moving to another operational assignment.', 'cf8696640d19438f2dbd875bea11edc6ecfa5469b6804811fd6adaf41573360d', 4, 4, null, 2, null, null, false, null),
  ('d4613845-ce34-5a4f-b177-f7ffdd45449e', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-1..O-2', null, 'Lieutenant — Developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Junior officers initially assigned to a CONUS or overseas installations (OCONUS) will be stabilized at their first installation for an extended period of time that allows for branch advancement to the rank of captain. This initial extended tour may include hardship tours or attendance at leader development schools (in TDY or PCS status) but in each case, the officer should return to their stabilization installation. Lieutenants should serve at the platoon and company level to gain troop leading and flight experience. The officer will concentrate on planning and executing the tactics, techniques, and procedures specific to their weapons platform and unit mission.', 'ea9f146545e927050d430aa0b12cf1d4b47e06f4587d1762e411b5b01e7ec4b3', 4, 4, null, 3, null, null, false, null),
  ('ff6dca06-d1ec-53be-88ac-ba20dfa2468f', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'self_development', 'O-1..O-2', null, 'Lieutenant — Self-development', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'All officers should be afforded every opportunity to achieve qualification as a pilot-in- command prior to attendance of the Aviation Captains Career Course (AVCCC) or CCC equivalent. A lieutenant’s focus should be to refine troop-leading, aviator, tactical, logistic (maintenance and supply), force protection (risk management) and administrative skills. The key milestone in a lieutenant’s development should be attaining pilot-in- command status. In doing so, lieutenants will acquire much needed technical and tactical experience, which will serve them well in future assignments. For example, company commanders are expected to set the standard for other pilots within their company. Being a pilot- in-command better enables commanders to be in the position to direct critical assets where needed. Lieutenants should also strive to obtain key training experiences that enhance normal garrison training, including, but not limited to: CTC rotations, joint and combined exercise deployments, and worldwide contingency operations. To successfully compete for promotion to captain, an officer must possess a thorough knowledge of Aviation tactics and principles and have obtained a baccalaureate degree. Officers may take advantage of pre-commissioning educational incentives such as incurring an additional 3-year ADSO in exchange for the opportunity to pursue a master’s degree later in their careers.', '686c9aa7d775b12c05f5e6072d3f73a04370b92f02e1cc6e6a216f377f5cbbbe', 4, 4, null, 4, null, null, false, null),
  ('93069eb0-aa13-5028-befa-eacca8e3e885', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-3', null, 'Captain — overview', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'A captain must successfully complete a branch CCC.', 'ff09ec8d0ab2f11a5b254192436879a2d284826b2f74e9cf0744f5add252f749', 4, 4, null, 5, null, null, false, null),
  ('a96d81c3-2407-52d3-a1d7-d646cd367e04', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'training', 'O-3', null, 'Captain — Professional military education', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', '(a) Captains Career Course. Captains must earn a baccalaureate degree prior to attending a CCC. Aviation officers will attend a branch CCC between their 5th and 8th year of commissioned service and will be awarded AOC 15B upon successful completion. Aviation officers may attend other branch’s CCC. The branch phase of the AVCCC is 21 weeks. It prepares officers to serve as combined arms experts, company commanders and battalion/brigade staff officers. The AVCCC meets established prerequisites for total operational flying duty credit assignments. Aviators earn 1 month of total operational flying duty credit for each month spent at AVCCC. Aviators attending another branch CCC do not earn total operational flying duty credit.
(b) Military Intelligence Captains Career Course. Officers selected for AOC 15C (All-Source Intelligence Officer) attend the Military Intelligence Officer Transition Course if they did not attend Military Intelligence BOLC. The AOC 15C officers attend the 20-week Military Intelligence CCC and receive training as a branch 35 (All-Source Intelligence Officer). They attend the Fixed Wing Multi-Engine Qualification Course before or after the Military Intelligence CCC with appropriate follow-on Aircraft specific training.
(c) Aviation Captains Career Course. Officers selected for AOC 15D Aviation Maintenance Officers will attend either the AVCCC or the CLC3. The officer will attend the Aviation Maintenance Officers Course for AOC 15D designation. The Maintenance Test Pilot Course is preferred when course funds and slots are available.', '9da6e04e0d616a64c29ae9d75e6163185897ed02289aedc665d010118555b7bc', 4, 4, null, 6, null, null, false, null),
  ('1c0df131-cfa9-5b53-9fb0-37cb9b4f8d97', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-3', null, 'Captain — Key developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Captains serving in one of the following assignments for 12–24 months acquire KD time:
(a) Platoon leader (15D) in an Aviation support company.
(b) Captain-level company/detachment command.', '2ef2a17bacb7040f4ab75c3bd79707d5b67e2d34102dc6d39007a42b36557c66', 5, 5, null, 7, null, null, false, null),
  ('223c3b88-94aa-5685-91bc-100e0107265f', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-3', null, 'Captain — Developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Captains are utilized as the senior leader at the company level. Their primary goal is to successfully command a TOE/TDA company for 18–24 months. Captains can hold platoon leader positions in units authorized captains as platoon leaders. These units include the Aviation Support Company and ARSOA units. Captains also fill key staff positions at the battalion and brigade level, in addition to positions within the brigade Aviation element, Air Defense Airspace Management (ADAM) cell, CTC/observer/controller positions, and small group instructor positions at the proponent and USMA. Even when assigned to staff positions, captains should continue to hone their direct leadership skills, build flight experience, and achieve/maintain pilot-in-command status.', '7e536b5b0b0cdfc54f46f08459ee00215fda04c35b234285b800dc5a218b5717', 5, 5, null, 8, null, null, false, null),
  ('59cbd431-e796-5be4-a318-d2e8c85232d0', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-3', null, 'Captain — Broadening assignment', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Opportunities available for captains include, but are not limited to:
(a) Observer controller/evaluator at a CTC.
(b) Course manager/instructor at USAACE/USAIC USMA.
(c) Training With Industry.
(d) HRC assignments.
(e) Collection manager (15C).
(f) Battalion primary and CAB assistant staff officer.
(g) Brigade Aviation element.', '50439ca7f942080fe51ba723cd8f599386277820a60384f82e4a800163aa5833', 5, 5, null, 9, null, null, false, null),
  ('eb15cbb2-3d2a-5dd6-a0c9-2aa9bcfa9f76', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'self_development', 'O-3', null, 'Captain — Self-development', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Captains should gain an in-depth understanding of Aviation brigadeoperations, combined arms operations, and aircraft maintenance. Aviation captains should dedicate time to a professional reading program to gain a historical perspective on solutions to tactical and leader challenges. Captains should strive for the same qualitative leadership building experiences as during their lieutenant years: CTC rotations, joint and combined exercises, and deployment on real-world contingency operations. The challenges at the captain/commander level will greatly enhance the officer’s tactical and technical skills, as well as build critical flight experience. Captains should strive to meet the requirements for award of the Senior Aviator Badge by the time they are promoted to major. Captains should broaden their understanding of warfighting through extension courses and independent study. Commanders should maintain healthy officer professional development programs within their units.', 'dd432d55a56ad9bba1514476ed6e9e308e8b7a8804a99678b52edf238eb65bc4', 5, 5, null, 10, null, null, false, null),
  ('8ee7c344-32a1-50f4-a0f3-87ac9eec881c', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-3', null, 'Captain — Key developmental', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Captains should seek the KD assignments that assist them in promotion and create the qualities of a tactically and technically proficient Aviation officer. In addition, opportunities exist at TRADOC organizations as staff and logistics officers.
(a) Aviation captains can request to attend the Joint Air Ground Operations School at Hurlburt Field, FL 32544, or the Aviation Air Cavalry Leaders Course at Fort Benning, GA 31995–3781 or the Aviation Cavalry Leaders Course Fort Rucker,AL.. If attendance at Air Ground Operations School is desired, the 3- week Joint Air Tasking Order Process Course located at Hurlburt Field, FL is recommended for officers who are required to understand and apply airspace mission command and the application of the air tasking order. The 2–week Joint Firepower Course at Nellis Air Force Base, Nevada, is more suited to an understanding of the application of joint fire support systems.
(b) Project Warrior is a program in which captains serve 2 years as an observer-coach-trainer at a maneuver combat trainer center, followed by 2 years as a small group instructor at a TRADOC Center of Excellence. Project Warrior was suspended due to operational requirements in Iraq and Afghanistan. The intent in reinstituting Project Warrior is to infuse observations, insights, and lessons gained from multiple maneuver combat trainer center decisive action rotations against hybrid threats, back into the force through the TRADOC Center of Excellence.
(c) Officers may receive Advanced Civilian Schooling or Expanded Graduate School Program participation if career timeline permits or if necessary for a FA or special assignment (for example, Army Acquisition Corps, FAO or USMA instructor). See Part One of DA PAM 600-3 for specifics.', 'adfab910469f8ab17fa4e194c287903e0b91503822e47811c8cdecc9346f4cc6', 5, 5, null, 11, null, null, false, null),
  ('b4781acf-27ce-5c66-a717-e0a53b762781', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-3', null, 'Captain — Volunteer Transfer Incentive Program', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'VTIP boards meet to consider officers in their seventh year of service for designation into other FAs or Branches. Officers will submit their top three choices at the seven- year mark. Officers receive a new career manager upon selection by the VTIP for a different branch or FA. Only a limited number of Aviators will be given a FA or branch outside of Aviation, usually based on specific Aviation skill requirements in select FAs. Aviation officers will not participate in the Army’s 4 Year VTIP.
(a) Volunteer Transfer Incentive Program eligibility. To participate in the VTIP officers must be eligible for transfer based on “in/out call” matrix provided in each MILPER message prior to each VTIP board. The officer must be an ACC officer. Must be a first lieutenant promotable, captain, or captain promotable. officers must submit a DA Form 4187 (Personnel Action) (signed only by the officer requesting the transfer, block 9), a memorandum for record (MFR) stating reason for request and one letter of recommendation from a lieutenant colonel or higher. Officers must submit their request electronically to usarmy.knox.hrc.mbx.opmd-retention@mail.mil. Any questions or concerns about the VTIP program or eligibility can be addressed via email at usarmy.knox.hrc.mbx.opmd- retention@mail.mil.
(b) An aviator migrating out of the Operations functional category will serve in their new FA for the remainder of their career, and with the exception of FA 51. Acquisition will no longer be authorized Aviation pay. Repetitive operational flying assignments through the grade of captain are critical in order for officers to make their first Aviation pay gate (96 months of credible operational flying duty assignments at the 12-year Aviation pay gate audit). If an aviator has not met their 12 year gate requirements, they will lose continuous Aviation pay beyond the 12th year of Aviation service unless they are assigned to a credible operational flying duty authorization, and continue to ’fly for pay’. Aviators who remain in Aviation Branch are expected to remain eligible to serve in operational Aviation assignments. See additional sections in this pamphlet and AR 611–110 for a complete description of each functional designation and associated skills.', 'b043c8f3d082d3fb9608f433eaa0ec6589ecc1c086bfd045666a334c6d03547c', 5, 6, null, 12, null, null, false, null),
  ('0259c99f-5b01-5d8c-ba5b-205f1eb9f3b1', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-3', null, 'Captain — Army Acquisition Corps', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Between the 7th and 8th year of service select officers are assessed into the Army Acquisition Corps by a HQDA selection board. Aviators assessed into Army Acquisition Corps do not compete for Aviation battalion or brigade commands. Instead, they compete for lieutenant colonel and colonel-level product, project and program manager positions. Officers assessed into the Army Acquisition Corps are re-designated with FA 51. Accession into FA 51 is based on the same criteria as mentioned above (Army needs, training and background, and officer skills). Again, Aviation Branch will only access enough aviators into the Army Acquisition Corps to meet Army Aviation acquisitionrequirements.', 'd9950b031fe9d60f730efbb6f758b2723ead33a0b4a10749dbb0e3bdb0bd93fe', 6, 6, null, 13, null, null, false, null),
  ('833d4456-6a89-515a-b557-1d309edb38a0', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-3', null, 'Captain — Army Special Operations Aviation', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Officers interested in joining the ARSOA, 160th Special Operations Aviation Regiment should understand the flight and leadership experience needed to be competitive for an ARSOA assessment. The ARSOA recruiters focus their recruiting efforts on experienced captains with solid leadership and flight experience. Interested captains should pursue company command as soon as possible following the CCC.', '2f519055d27bba7190310532ca54874cd4fb3e9333c31ed9c472886b683094ba', 6, 6, null, 14, null, null, false, null),
  ('ad7c00e5-6902-57d3-8b89-ed2c98b8ce76', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-4', null, 'Major — overview', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Majors should complete the Command and General Staff College/ILE course, a sister Service equivalent institution (Navy, Marine, or Air Force), or schools in other nations before they enter the primary zone of consideration to be competitive for promotion to lieutenant colonel.', 'e961361d01987af2d1a86bd871ed8e687c60ccf9d774e1a1afe90c775622ff19', 6, 6, null, 15, null, null, false, null),
  ('8357d3d2-78f0-56b8-b368-bf374aa553df', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'training', 'O-4', null, 'Major — Professional military education', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Following Command and General Staff College/ILE, some officers are selected to attend the SAMS. Those officers selected for the SAMS must serve an initial utilization tour as an assistant plans officer for DCS, G–3/5/7 on division or Corps staffs. Aviation maintenance officers are encouraged to attend the Army Logistics Management Course (Support Operations).', '9f3b8430af5a9b54fcbbf882e83cdcb881c58dc7cf959d71101ed4a67686c22d', 6, 6, null, 16, null, null, false, null),
  ('792b0248-78bf-51ff-9c81-7649b8e8010f', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-4', null, 'Major — Key developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Majors regardless of their AOC (B, C, or D) should seek KD assignments that assist them in promotion, either in the Aviation Branch or in a FA. Majors should seek KD assignments and should serve in one or more of the following assignments for 12 to 24 months to acquire KD time:
(a) Battalion/brigade XO.
(b) Battalion/brigade S3.
(c) Command positions coded for majors.
(d) AOC 15B. Majors’ KD assignments include Aviation combined arms operating generating force assignments as battalion CAB staff, company command, and brigade Aviation officer.
(e) AOC 15C. Majors’ KD assignments include Aviation combined arms operating generating force assignments as well as CAB S2 and aerial exploitation battalion S3 and XO. Additional broadening opportunities include Aviation staff positions in Military Intelligence brigades, tactical intelligence groups, and division levels all source collection elements.
(f) AOC 15D. Majors’ KD assignments include Aviation Combined Arms operating generating force assignments as well as battalion staff in tactical battalions, major level company command assignments as well as Aviation support company command, Aviation support battalion/XO/support operations, brigade S4, and division Aviation maintenance officer. Additional opportunities exist at Army Materiel Command (AMC) depots and in Theater Aviation Sustainment Maintenance Groups', 'a3baf2c6d869c8e485e928af9eddd46e1c5484003fc99bf394a9b2c08eb8cd02', 6, 6, null, 17, null, null, false, null),
  ('d5f20c4c-aaed-55ea-a508-c539852614fb', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-4', null, 'Major — Developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Aviation staff positions are at the battalion, brigade, group, HQDA, and joint staff levels. Some majors also serve as instructors or hold staff positions at Army service schools.', '3d9d99e6181b0c51e42ff26953df5d7cf831724805d58f64b4861ecb4215a9fd', 6, 6, null, 18, null, null, false, null),
  ('3e35d339-944e-520c-839e-758a1966bc2d', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-4', null, 'Major — Broadening assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Opportunities available for majors include, but are not limited to:
(a) CTC observer controller/evaluator.
(b) RC advisor.
(c) USAREC staff.
(d) USMA faculty and staff.
(e) TRADOC service school instructors/doctrine writers.
(f) Army Staff, joint staff and branch/FA generalist positions.
(g) Security Forces Assistance Brigade', '46e222131b7c02ee398603f2c0e57c37057a5e6e556bccfb2279f3f8a6e8cea0', 7, 7, null, 19, null, null, false, null),
  ('baa9b3c0-8bdb-5bf7-bb1c-98e50d4fccfa', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'self_development', 'O-4', null, 'Major — Self-development', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Majors should focus self-developmental efforts on acquiring expertise in organizational leader- ship techniques, operations at division level and above, Aviation logistical support operations. Their self-development must focus on joint, multinational, and combined arms operations. This can be accomplished through correspondence courses or institutional training. Majors should devote time to a professional reading program. Officers may take advantage of the Expanded Graduate School Program and attend advanced civilian schooling if the follow-on assignment requires an advanced degree. Many advanced degree programs are available in order for officers to obtaina graduate degree. Aviation majors will likely serve in operational flying positions after being away from the cockpit for some time due to schooling and required staff positions. Therefore, their self-development should also be focused on refreshing themselves with new Aviation technologies in the cockpit. They should set the example for the younger generation of officers by continuing to place a strong emphasison their technical and tactical Aviation proficiency. Aviation majors in BR 15 should strive to attain the Master Aviator Badge by the time they are promoted to lieutenant colonel should seek a field grade joint duty assignment once tactical and technical experiences have been attained.', 'ed028ec0657faa85158ef72a8d64cc2d5557cc9acf3614a3af21287380125b48', 7, 7, null, 20, null, null, false, null),
  ('401aee98-a131-5adc-ba09-24759bffb7b5', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-4', null, 'Major — Selection', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Individuals selected and assigned to a brigade Aviation element or ADAM Cell may be selected by the CAB commander to serve in positions organic to the BCTs as the Aviation subject matter expert for the BCT commander. Ideally, these positions will serve as a second KD position fora major, after they have completed an S3/ XO positions. Officers assigned to a brigade Aviation element/ADAM cell provide the critical linkage with the BCT’s supporting CAB to facilitate the most efficient tactical employment of Aviation assets in the BCT’s operational environment. Serving in a similar position at a higher level also satisfies this intent.', '1342584c2946f19b24f875b778a2f8700f7e6fa69f037e2cced73d8d252ef917', 7, 7, null, 21, null, null, false, null),
  ('4241c8cf-b630-5b1f-86d5-8c516b340d98', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-5', null, 'Lieutenant colonel — overview', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Lieutenant colonels should serve in an Aviation-coded position for 18 to 24 months.', '9c18006d14759e87865e3dc2efce51484cfc514921332276a7e531135a8b71e5', 7, 7, null, 22, null, null, false, null),
  ('7a47954f-505c-5859-98d2-025a882fdfd4', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'training', 'O-5', null, 'Lieutenant colonel — Professional military education', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'No specific military education requirements exist for lieutenant colonels. A HQDA board determines selection for resident SSC or the U.S. Army War College Distance Education Course. Officers selected for command selection list battalion command will attend the Army’s PCC at Fort Leavenworth, KS, and the Aviation PCC at Fort Rucker, AL. Select TDA battalion command designees may also be slated for attendance at the TRADOC PCC at Fort Jackson, SC. Battalion command designees who have special courts martial convening authority will attend the Senior Officers Legal Orientation Course at Charlottesville, VA. A master’s degree is strongly recommended, but is not required for promotion. Aviation maintenance officers are strongly encouraged to attend the Army Logistics Management College (Senior Leaders Course).', '4df0fa450381618d3762be764c777d8baeff04d40a76bd9bf68ca0d747b750b3', 7, 7, null, 23, null, null, false, null),
  ('3ea9d5b0-5ceb-5a64-abaa-5e3de9d1040d', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-5', null, 'Lieutenant colonel — Key developmental', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Lieutenant colonels should seek (KD) assignments that assist them in promotion, either in the Aviation Branch or in a FA. Lieutenant colonels serving in one of the following assignments for 12 to 24 months acquire KD time.
(a) Battalion commander.
(b) Brigade deputy CDR/XO/S3.', 'a4c07dc5ad698022c4ee2f843e976f0a9c65c9df99ce470a85531417f2a07eab', 7, 7, null, 24, null, null, false, null),
  ('ef5397c4-e422-5577-891c-5ed7817cb532', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-5', null, 'Lieutenant colonel — Developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Lieutenant colonels that successfully complete a CSL battalion-level command may remain competitive for promotion to colonel, brigade command, and SSC selection. Commands on the CSL are organized into four functional categories: operations, strategic support, recruiting and training, and installation. The following assignments are not necessarily coded as Aviation, however they are considered developmental assignments: lieutenant colonel positions at the CTCs, brigade/regiment/corps assistant for DCS, G–3/5/ 7 or DCS, G–4, deputy assistant for DCS, G–3/5/7 or DCS, G–4, operations officer for DCS, G–3/5/7, assistant plans officer for DCS, G–3/5/7, ROTC or recruiting duty, ACOM/ASCC/DRU staff, Army Staff, joint staffs, and selected AA/RC assignments. Performance in demanding assignments is a prime consideration for promotion and school selection boards. Officers should complete a field grade joint duty assignment to be competitive for promotionto brigadier general.', '27358fa1a2f9e26a60cd45d3ae0ae00f3a0a06b0456bf275451f1d103fd915fd', 7, 8, null, 25, null, null, false, null),
  ('a6b0cf43-eeb5-5675-9af7-1b976bfbdc67', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-5', null, 'Lieutenant colonel — Broadening assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'The following assignments are not necessarily coded as Aviation; however, they are considered broadening assignments. Lieutenant colonel positions at USAACE, CTCs, brigade/regiment/group XO, division primary staff, corps assistant for DCS, G–3/5/7 or DCS, G–4, deputy assistant for DCS, G–3/5/7 or DCS, G–4, operations officer for DCS, G–3/5/7, assistant plans officer for DCS, G–3/5/7, ROTC or recruiting duty, ACOM/ ASCC/DRU staff, Army Staff, joint staffs, and selected AA/RC assignments are designated as broadening. Performance in demanding assignments is a prime consideration for promotion and school selection boards. Lieutenant colonels should also seek a joint duty assignment.', '6e83b08d66245f9a8caa9b1c8d526997c4164c907b87693b1fdf9566ef289903', 8, 8, null, 26, null, null, false, null),
  ('a0013db9-14f0-5f77-9f6a-6efd44178589', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'self_development', 'O-5', null, 'Lieutenant colonel — Self-development', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Officers should continue to build warfighting, joint, expeditionary, and FA expertise.', '630b365e78a511c6d6b51a52c3876a0297be616519f4320d4c3b7be2df2ca4db', 8, 8, null, 27, null, null, false, null),
  ('dfe1194d-9bac-5d44-af72-b895655d1452', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'development', 'O-6', null, 'Colonel — overview', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'The professional development objective for this phase of an officer’s career is sustainment of warfighting, training, and staff skill, along with utilization of leadership, managerial and executive talents. The majority of strategic level leaders in the Army are colonels. Colonels are expected to be multi-skilled leaders, strategic and creative thinkers, builders of leaders and teams, competent decisive action warfighters, skilled in governance, statesmanship, and diplomacy, and understand cultural context and work effectively across it. Aviation colonels are assigned by the Army’s Senior Leader Development Office. Colonels should serve 18–24 months in an Aviation assignment coded at the grade of colonel.', '677c52d046ab5da13ac7ecda9aeb01165d5bc90762e3b73757147e1115a401e4', 8, 8, null, 28, null, null, false, null),
  ('65cf66da-bde7-5b95-9deb-bea85685f46d', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'training', 'O-6', null, 'Colonel — Professional military education', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Although no specific mandatory military education requirement exists for colonels, the primary professional development goal is completion of SSC. Resident or nonresident Attendance at a SSC also identifies those officers with exceptional promotion potential for service in positions of increased responsibility. An HQDA board determines who attends the resident course and participates in the U.S. Army War College Distance Education Course. Officers selected for CSL brigade Command will attend the Army’s PCC at Fort Leavenworth, KS, and the Aviation PCCat Fort Rucker, AL. Brigade command selectees may attend the Senior Officers Legal Orientation Course at Charlottesville, VA. Officers selected as TRADOC capability managers (TCMs) will attend the Combat Developers Course at Fort Lee, VA and the Project Manager’s Acquisition Category III Course (commonly known as the Project Manager’s Survival Course) at Fort Belvoir, VA. The Acquisition Category III Course has several prerequisites. Officers selected for TCM billets should contact their assignment officer to discuss requirements.', '5e038d0e9d54a0e19fbb3472ecdd61ed61ccc0f3211f43e5e0a81bc0e1b9fba3', 8, 8, null, 29, null, null, false, null),
  ('12c9363c-e418-56ae-b92f-217fb3803440', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-6', null, 'Colonel — Key developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Colonels serving in brigade command for 12 to 24 months acquire KD time. Successful brigade-level command marks officers as qualified for increased responsibility at the highest levels in the Army and DOD.', '2763146cd801dcead7ea1198d0db277e95089ae2922f3600352db195b8d3ec33', 8, 8, null, 30, null, null, false, null),
  ('418e8029-f6c5-54da-81f8-669cf0b286b1', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-6', null, 'Colonel — Developmental assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'The following positions (some not necessarily coded as Aviation) are also developmental assignments: senior-level joint duty, division (former brigade commander position), corps-level officer for DCS, G–3/5/7, or DCS, G–4, U.S. Army Aviation and Missile Command, or deputy chief of staff, deputy assistant commandant, director of training development and doctrine, director, TRADOC program office-Aviation brigades, director of evaluation and standardization (DES), director of simulations, director, organization and personnel force development, chiefs of staff (at division, corps, USAACE) colonel positions at the CTCs, Army Staff, ACOM/ASCC/ DRU staff, joint staffs, and selected AC/RC assignments.', 'd76dfe36108f4c57a2b35b52e857a2785eda29bda8dcfbf371709d8e27dfbedc', 8, 8, null, 31, null, null, false, null),
  ('e7fc641d-224f-5c80-8c2f-697003958ade', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'assignments', 'O-6', null, 'Colonel — Broadening assignments', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'The following assignments are not necessarily coded as Aviation, however they are considered key broadening assignments: colonel positions at CTCs brigade/regiment/group XO, division primary staff, corps assistant for DCS, G–3/5/7 or DCS, G–4, deputy assistant for DCS, G–3/5/7 or DCS, G–4, operations officer for DCS, G–3/5/7, assistant plans officer for DCS, G–3/5/7, ROTC or recruiting duty, ACOM/ASCC/DRU staff, Army Staff, joint staffs, and selected RA/RC assignments. Performance in demanding assignments is a prime consideration for promotion and school selection boards. Colonels should also seek a joint duty assignment. Officers should complete a field grade joint duty assignment to be competitive for promotion to brigadier general.', '941a6ccfa2c399446ebff06942fddef2b06f79ee20c56b7e55dfe40635e52c0e', 8, 8, null, 32, null, null, false, null),
  ('82e33e81-b4cd-5f09-a427-f97a6bfe82cd', '94f1d82f-9b7b-5be8-80fb-1f964e2e2fa2', 'Army', 'officer', '15A', 'AVIATION, GENERAL', 'self_development', 'O-6', null, 'Colonel — Self-development', 'Aviation Branch officer career pamphlet, DA PAM 600-3 chapter (30 June 2021)', 'Self-development goals should focus on perfecting organizational level leadership skills, joint and coalition operations, and theater-level operations. An advanced degree is not required but is strongly recommended.', 'd1e226ec90c32f62d8bc3b20c9c02761ac2947773a3fddf624dbd6da576b5cdb', 8, 9, null, 33, null, null, false, null);
